from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split()
    frequency = tokens[0]
    step = int(tokens[1])
    result = []
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if frequency == "DAILY":
        return [
            (start_date + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in tokens[2].split(","))
        monday = start_date - timedelta(days=start_date.weekday())

        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if frequency == "MONTHLY":
        month_index = start_date.year * 12 + start_date.month - 1
        ordinal = int(tokens[2])
        target_weekday = weekdays[tokens[3]] if len(tokens) == 4 else None

        while True:
            year, zero_based_month = divmod(month_index, 12)
            month = zero_based_month + 1
            first_weekday, days_in_month = monthrange(year, month)

            if target_weekday is None:
                day = days_in_month if ordinal == -1 else ordinal
            elif ordinal == -1:
                last_weekday = (first_weekday + days_in_month - 1) % 7
                day = days_in_month - (last_weekday - target_weekday) % 7
            else:
                day = (
                    1
                    + (target_weekday - first_weekday) % 7
                    + 7 * (ordinal - 1)
                )

            if day <= days_in_month:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result

            month_index += step

    if frequency == "YEARLY":
        month, day = map(int, tokens[2].split("-"))
        year = start_date.year

        while True:
            if day <= monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            year += step
